// Build the provider request. Non-reasoning on BOTH sides (ADR 0001): the doer is
// gpt-4.1-mini with strict structured output, the judge is gemini-2.5-flash with its thinking
// budget set to zero. Two vendors, one door.
//
// The caller picks with `provider`, and everything else about a call is identical: same
// envelope in, same envelope out, same classifier, same cost row. A caller that names no
// provider gets the doer, which is every caller written before E7-S5.

// Gemini's responseSchema is an OpenAPI subset: it has no `additionalProperties` and wants
// its type names upper-cased. Dropping the key does NOT open the schema - Gemini emits only
// declared properties, and the code that reads the answer takes only the fields it knows
// (layer 2 is about what a schema OFFERS an obeyed instruction, and this offers nothing new).
function toGeminiSchema(s) {
  if (!s || typeof s !== 'object') return s;
  const t = Array.isArray(s.type) ? s.type[0] : s.type;
  const g = {};
  if (t) g.type = String(t).toUpperCase();
  if (s.description) g.description = s.description;
  if (Array.isArray(s.enum)) g.enum = s.enum;
  if (t === 'object') {
    g.properties = {};
    for (const [k, v] of Object.entries(s.properties ?? {})) g.properties[k] = toGeminiSchema(v);
    if (Array.isArray(s.required)) g.required = s.required;
    g.propertyOrdering = Object.keys(s.properties ?? {});
  }
  if (t === 'array') g.items = toGeminiSchema(s.items);
  return g;
}

const MODELS = { openai: 'gpt-4.1-mini', gemini: 'gemini-3.8-flash' };

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const provider = j.provider === 'gemini' ? 'gemini' : 'openai';
  const model = MODELS[provider];

  const _meta = {
    prompt_name: j.prompt_name ?? 'unknown',
    prompt_version: j.prompt_version ?? null,
    component: j.component ?? 'unknown',
    trace_id: j.trace_id ?? null,
    doc_id: j.doc_id ?? null,
    provider,
    model,
    started_at: Date.now(),
  };

  if (provider === 'gemini') {
    out.push({
      json: {
        _meta,
        provider,
        model,
        // The thinking budget is zero and it is set here, not hoped for: a reasoning model
        // would break the project's own cost discipline in the one place nobody looks.
        gemini: {
          systemInstruction: { parts: [{ text: j.system }] },
          contents: [{ role: 'user', parts: [{ text: j.user }] }],
          generationConfig: {
            temperature: 0,
            responseMimeType: 'application/json',
            responseSchema: toGeminiSchema(j.schema),
            thinkingConfig: { thinkingBudget: 0 },
          },
        },
      },
    });
    continue;
  }

  out.push({
    json: {
      _meta,
      provider,
      model,
      temperature: 0,
      messages: [
        { role: 'system', content: j.system },
        { role: 'user', content: j.user },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: j.prompt_name ?? 'response', strict: true, schema: j.schema },
      },
    },
  });
}
return out;

// Parse, and decide honestly whether this is a result or a park.
//
// BUG-011: every provider failure except one used to be recorded as `llm_timeout`, which
// sent whoever read it to look at latency and network. The classifier below is a COPY of
// review-ui/llm-errors.mjs (a Code node cannot import); verify-degradation.mjs runs both
// copies over the same cases and fails when they disagree.
function classifyProviderError(err) {
  const status = Number(err?.status ?? err?.httpCode ?? err?.response?.status ?? 0);
  const code = String(err?.code ?? '');
  const message = String(err?.message ?? '');
  const text = `${code} ${message}`.toLowerCase();

  // Ordered, and the order is load-bearing: a 401 whose message happens to contain the
  // word "timeout" is an auth failure, not a timeout.
  if (code === 'context_length_exceeded') return 'llm_malformed_json';
  if (status === 401 || status === 403
    || /unauthor|forbidden|invalid[_ ]api[_ ]key|api key|credential|authenticat/.test(text)) {
    return 'llm_unauthorized';
  }
  // An exhausted BALANCE is not rate limiting. It arrives as a 429 with an
  // `insufficient_quota` code, so it must be matched before the rate-limit clause or it
  // borrows a code that means "wait, it will pass" — and this one never passes on its own.
  // Found by a real outage rather than a drill (BUG-036).
  if (/insufficient[_ ]quota|no credits|credit balance|billing|exceeded your current quota|add credits/.test(text)) {
    return 'llm_no_credit';
  }
  if (status === 429 || /rate[_ ]limit|too many requests|quota/.test(text)) return 'llm_rate_limited';
  if (status === 408
    || /timeout|timed out|etimedout|esockettimedout|econnaborted/.test(text)
    || /connection was aborted/.test(text)) {
    return 'llm_timeout';
  }
  return 'llm_error';
}

//
// One retry already happened at the HTTP node. If we still cannot parse, the run parks as
// `needs_review` with a machine-readable reason — never a partial result, and never a
// second vendor (docs/architecture.md, degradation table).
//
// TWO PROVIDERS ARRIVE HERE (E7-S5) and are read by the SAME classifier. Only the shape of
// the reply differs, so only the shape is normalised below: where the text is, where the
// token counts are, and where the error object lives. A second classifier would be a second
// place for BUG-011 to happen.
// WHICH ATTEMPT THIS IS, asked rather than assumed. `Build retry` throws when it has not
// run, which is exactly the question "is this the first attempt?" — and it is asked of the
// execution rather than tracked in a variable that a second pass would not share.
// BUG-041. A provider's error message is BOILERPLATE-FIRST and SPECIFIC-LAST. Google's quota
// error spends its first 220 characters on prose and two documentation URLs, and then names the
// metric — which is the only part that says WHICH quota was exceeded, and so whether this is a
// daily cap, a rate limit, or a key that never reached the paid tier. A head truncation throws
// away exactly the half worth storing, and on 2026-09-04 it did: the record could not tell those
// three apart and the diagnosis had to come from counting calls per hour instead.
//
// The cap stays. An unbounded provider string in a database column is how a log becomes a
// liability. What changes is how the cap is SPENT: both ends, and the join is visible so nobody
// reads a spliced string as a whole one.
const bounded = (s, n = 300) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= n) return t;
  const head = Math.ceil((n - 5) * 0.55);
  return `${t.slice(0, head)} … ${t.slice(t.length - (n - 5 - head))}`;
};

let meta;
try {
  meta = $('Build retry').first().json._meta;
} catch {
  meta = $('Build request').first().json._meta;
}
const latency_ms = Date.now() - meta.started_at;
const isGemini = meta.provider === 'gemini';
const out = [];

for (const item of $input.all()) {
  const r = item.json ?? {};
  const base = {
    envelope_version: '1.0',
    trace_id: meta.trace_id,
    doc_id: meta.doc_id,
    component: meta.component,
    _call: {
      prompt_name: meta.prompt_name,
      prompt_version: meta.prompt_version,
      component: meta.component,
      model: meta.model,
      latency_ms,
      prompt_tokens: isGemini ? (r?.usageMetadata?.promptTokenCount ?? null) : (r?.usage?.prompt_tokens ?? null),
      completion_tokens: isGemini ? (r?.usageMetadata?.candidatesTokenCount ?? null) : (r?.usage?.completion_tokens ?? null),
      attempt: meta.attempt ?? 1,
    },
  };

  if (r.error) {
    // Gemini reports {error:{code:429, status:'RESOURCE_EXHAUSTED', message}}; OpenAI reports
    // {error:{status?, code:'insufficient_quota', message}}. Normalised into the one shape the
    // classifier reads, so the classifier itself stays identical to its two copies.
    const e = r.error?.error ?? r.error;
    const err = isGemini
      ? { status: Number(e?.code) || 0, code: String(e?.status ?? ''), message: String(e?.message ?? '') }
      : e;
    out.push({ json: { ...base, status: 'needs_review', payload: { reason: classifyProviderError(err), missing: [], detail: bounded(e?.message) } } });
    continue;
  }

  const content = isGemini
    ? r?.candidates?.[0]?.content?.parts?.[0]?.text
    : r?.choices?.[0]?.message?.content;
  if (!content) {
    out.push({ json: { ...base, status: 'needs_review', payload: { reason: 'llm_error', missing: [], detail: `no content returned: ${JSON.stringify(r).slice(0, 240)}` } } });
    continue;
  }

  try {
    out.push({ json: { ...base, status: 'ok', payload: JSON.parse(content) } });
  } catch (e) {
    out.push({ json: { ...base, status: 'needs_review', payload: { reason: 'llm_malformed_json', missing: [], detail: String(e.message).slice(0, 200) /* head-truncated on purpose: a JSON parse error is specific-first */ } } });
  }
}
return out;

// Return the envelope the caller asked for. The logging response is discarded: whether
// telemetry succeeded must never change what the pipeline returns.
return $('Parse or park').all();

// THE SECOND ATTEMPT. The same request, unchanged, with the attempt stamped on it.
//
// It is the same bytes on purpose: a retry that changed the prompt, the temperature or the
// schema would be a different experiment, and the two rows in `llm_calls` would no longer be
// comparable — which is the whole point of recording them separately.
//
// WHAT IT ACTUALLY BUYS, stated rather than implied: at temperature 0 this is not a fresh
// sample. It buys the small non-determinism the provider has left, and it is cheap. The
// durable value is the ATTEMPT-2 RATE (docs/traceability.md): a model that starts returning
// unparseable JSON more often says so here before it says so anywhere else.
const first = $('Build request').first().json;
return [{
  json: {
    ...first,
    _meta: { ...first._meta, attempt: 2, started_at: Date.now() },
  },
}];
